                  linearSolver = CeresLinearSolver.SPARSE_NORMAL_CHOLESKY,
                  functionTolerance = 1e-10,
                  gradientTolerance = 1e-14,
                  parameterTolerance = 1e-12,
                  summary = true,
              )

              fun solve(planes: PlaneFormulation) = CachedCeresSolvers(backend).use { solvers ->
                  solvers.solve(
                      SolveRequest(
                          PointCloud(problem.initialCoordinates),
                          CeresRealization.program(plan, problem, planes, 1.0),
                          options = options,
                      ),
                  )
              }

              // Each face's plane as a free unit normal (on a sphere manifold) plus a free scalar
              // offset, written in Kotlin as `corner . n - d` — and the same parameterisation as the
              // hand-written C++ opcode, so the two can be compared on the spot.
              val expressed = solve(PlaneFormulation.HESSE_EXPRESSION)
              val opcode = solve(PlaneFormulation.HESSE)
              val agreement = expressed.points.values.indices.maxOf {
                  kotlin.math.abs(expressed.points.values[it] - opcode.points.values[it])
              }

              val solved = seed.copy(
                  realization = Realization3(
                      (0 until problem.vertexCount).map { i ->
                          Vec3(
                              expressed.points.values[3 * i].toFloat(),
                              expressed.points.values[3 * i + 1].toFloat(),
                              expressed.points.values[3 * i + 2].toFloat(),
                          )
                      },
                  ),
              )

              // The free variables, read back in declaration order: two blocks per face, a unit normal
              // and an offset. They are not in the point cloud — they never were points.
              val planes = faces.indices.map { f ->
                  expressed.variables[2 * f].vec3() to expressed.variables[2 * f + 1].scalar
              }
              val worstUnit = planes.maxOf { (n, _) ->
                  kotlin.math.abs(kotlin.math.sqrt(n.x * n.x + n.y * n.y + n.z * n.z) - 1.0)
              }
              val diagnostics = solved.canonicalDiagnostics()

              println(
                  """
                  $expression — ${solved.topology.elements(0).size} vertices, ${solved.topology.elements(1).size} edges, ${faces.size} faces
                  ${expressed.variables.size} free variables (${planes.size} planes: a unit normal + an offset each)
                  expression : ${expressed.summary}
                  opcode     : ${opcode.summary}
                  the two answers differ by at most ${"%.2e".format(agreement)}
                  canonical  : tangency spread ${"%.3e".format(diagnostics.tangencyRadiusSpread)}  centre ${"%.3e".format(diagnostics.tangencyCentroidOffset)}  planarity ${"%.3e".format(diagnostics.maxFacePlanarityError)}
                  every solved normal is still unit to ${"%.2e".format(worstUnit)} — the sphere manifold's own doing,
                  since no residual ever asks it to stay there
                  """.trimIndent(),
              )

              val status: (String) -> Unit = { message -> markdown("plane", message) }

              // Colour each face by how far its own corners sit from the plane Ceres solved for.
              val faceLines = solved.toFaceFLines { face, line ->
                  val f = faces.indexOfFirst { it.id == face.id }
                  val (n, d) = planes[f]
                  val cycle = solved.topology.faceCycle(face.id)
                  val index = solved.topology.elements(0).mapIndexed { at, v -> v.id.value to at }.toMap()
                  val corners = solved.realization!!.vertexCoordinates
                  val worst = cycle.maxOf { vertexValue ->
                      val p = corners[index.getValue(vertexValue)]
                      kotlin.math.abs(p.x * n.x + p.y * n.y + p.z * n.z - d)
                  }
                  line.filled = true
                  line.stroked = true
                  line.thickness = 1.2
                  line.color = vec(0.36, 0.78, 0.96, 0.72)
                  line.hoverColor = vec(0.99, 0.96, 0.62, 0.95)
                  line.onClick = {
                      status(
                          """
                          **face ${face.id.value} of ${faces.size}** — degree ${cycle.size}

                          Its plane is two free variables Ceres solved for, not geometry anyone supplied:

                          - normal `n` = `(${"%.6f".format(n.x)}, ${"%.6f".format(n.y)}, ${"%.6f".format(n.z)})`, on a sphere manifold
                          - offset `d` = `${"%.6f".format(d)}`
                          - `|n|` = `${"%.15f".format(kotlin.math.sqrt(n.x * n.x + n.y * n.y + n.z * n.z))}`
                          - worst corner off this plane: `${"%.3e".format(worst)}`

                          The residual is just `corner . n - d`, written in Kotlin and differentiated by
                          Ceres on `ceres::Jet` — no C++, no finite differences.
                          """.trimIndent(),
                      )
                  }
              }

              // One stem per free variable: from the point of that face's plane nearest the origin,
              // outward along the normal. Both endpoints come from `n` and `d` alone — this is the part
              // of the picture you cannot draw at all without reading the free variables back.
              val stem = 0.6
              val stems = planes.map { (n, d) ->
                  FLine()
                      .moveTo((n.x * d).toFloat(), (n.y * d).toFloat(), (n.z * d).toFloat())
                      .lineTo((n.x * (d + stem)).toFloat(), (n.y * (d + stem)).toFloat(), (n.z * (d + stem)).toFloat())
                      .also {
                          it.stroked = true
                          it.filled = false
                          it.thickness = 3.0
                          it.color = vec(1.00, 0.47, 0.18, 1.00)
                      }
              }

              threeLines(
                  faintSeed() + faceLines + stems,
                  channel = "solid",
                  name = "ceres-planes",
                  height = 560,
                  autoFrame = true,
                  editable = false,
              )
              displayOpen("solid")

              status(
                  """
                  ### ${planes.size} planes, solved for

                  Faint grey is the seed embedding; blue is the canonical form Ceres found; each orange
                  stem is one of the free variables — a unit normal, drawn from the point of its plane
                  nearest the origin.

                  Click a face to read its plane.
                  """.trimIndent(),
              )
              displayOpen("plane")
          }
  - create:
      box: ceres_free_variables_sphere
      name: "Ceres — unknowns that are not points"
      frame: { x: 580.0, y: 80.0, w: 350.0, h: 100.0 }
      properties:
        code: |
          import afield.geometry.path.FLine
          import afield.math.optimization.ceres.CachedCeresSolvers
          import afield.math.optimization.ceres.CeresExprVec
          import afield.math.optimization.ceres.CeresLinearSolver
          import afield.math.optimization.ceres.FfmCeresBackend
          import afield.math.optimization.ceres.PointCloud
          import afield.math.optimization.ceres.SolveOptions
          import afield.math.optimization.ceres.SolveRequest
          import afield.math.optimization.ceres.Vec3
          import afield.math.optimization.ceres.buildCeresProgram
          import afield.math.optimization.ceres.RobustLoss
          import java.nio.file.Files
          import java.nio.file.Path

          // ---- the data to fit -------------------------------------------------------------
          // Four points, so the answer has a closed form to check against: the circumsphere of a
          // tetrahedron. Add a fifth and it becomes a genuine least-squares fit instead.
          val data = listOf(
              Vec3(0.9, 0.6, 2.3),
              Vec3(1.0, -2.1, 0.5),
              Vec3(-0.4, 2.0, 0.5),
              Vec3(-0.4, -0.5, 2.3),
          )
          // ----------------------------------------------------------------------------------

          // Nothing is committed, so look where each build task puts its artifact. Constructing the
          // backend is what refuses a missing or too-old library, so that is the check.
          val backendFailures = mutableListOf<String>()
          val backend = listOf(
              Path.of("build/ken-ceres-redistributable/libken_ceres_jvm.dylib"),
              Path.of("build/ken-ceres/libken_ceres_jvm.dylib"),
          ).filter { Files.exists(it) }.firstNotNullOfOrNull { path ->
              runCatching { FfmCeresBackend(path) }
                  .onFailure { failure ->
                      val detail = "$path: ${failure.javaClass.simpleName}: ${failure.message}"
                      backendFailures += detail
                      println("Ceres load failed: $detail")
                  }
                  .getOrNull()
          }
          val backendStatus = when {
              backend != null -> "Loaded a compatible Ceres wrapper."
              backendFailures.isEmpty() -> "No Ceres wrapper found in build/ken-ceres-redistributable or build/ken-ceres."
              else -> "Ceres wrappers were found but could not load:\n" + backendFailures.joinToString("\n")
          }

          fun dots(): List<FLine> = data.map { p ->
              val s = 0.06f
              FLine()
                  .moveTo((p.x - s).toFloat(), p.y.toFloat(), p.z.toFloat())
                  .lineTo((p.x + s).toFloat(), p.y.toFloat(), p.z.toFloat())
                  .moveTo(p.x.toFloat(), (p.y - s).toFloat(), p.z.toFloat())
                  .lineTo(p.x.toFloat(), (p.y + s).toFloat(), p.z.toFloat())
                  .moveTo(p.x.toFloat(), p.y.toFloat(), (p.z - s).toFloat())
                  .lineTo(p.x.toFloat(), p.y.toFloat(), (p.z + s).toFloat())
                  .also {
                      it.stroked = true
                      it.filled = false
                      it.thickness = 3.0
                      it.color = vec(1.00, 0.52, 0.28, 1.00)
                  }
          }

          if (backend == null) {
              println("$backendStatus\nDrawing the data only.")
              markdown(
                  "fit",
                  """
                  ### This box needs the native Ceres wrapper

                  $backendStatus

                  Build or update the optional wrapper to solve the free centre and radius, then re-run:

                  ```
                  ./gradlew buildCeresRedistributable
                  ```
                  """.trimIndent(),
              )
              displayOpen("fit")
              threeLines(dots(), channel = "fit3d", name = "ceres-sphere", height = 480, autoFrame = true)
              displayOpen("fit3d")
          } else {
              // The unknowns are a centre and a radius. Neither is a point in the cloud — the data are
              // constants inside the expression, and this residual names no point at all. No opcode in
              // the vocabulary can say this: RADIUS_ABOUT_CENTROID fits a radius about the points' own
              // centroid, which is not the same thing as a free centre.
              val program = buildCeresProgram(RobustLoss.NONE) {
                  val centre = variable("centre", Vec3(6.0, -6.0, 6.0))   // a deliberately bad start
                  val radius = variable("radius", 0.1)
                  expression(emptyList(), [centre, radius]) { _, (c, r) ->
                      data.map { p -> (CeresExprVec.of(p) - c.vec()).length() - r.scalar }
                  }
              }

              val result = CachedCeresSolvers(backend).use { solvers ->
                  solvers.solve(
                      SolveRequest(
                          PointCloud.of(Vec3(0.0, 0.0, 0.0)),
                          program,
                          options = SolveOptions(
                              maxIterations = 200,
                              linearSolver = CeresLinearSolver.SPARSE_NORMAL_CHOLESKY,
                              functionTolerance = 1e-14,
                              gradientTolerance = 1e-16,
                              parameterTolerance = 1e-14,
                              summary = true,
                          ),
                      ),
                  )
              }
              val centre = result.variables.vec3("centre")
              val radius = result.variables.scalar("radius")

              // The closed form, for comparison: |c - p_i|^2 equal for every vertex, which after
              // subtracting the first equation is a 3x3 linear system. Solved by Cramer's rule.
              fun closedForm(): Pair<Vec3, Double> {
                  fun n2(v: Vec3) = v.x * v.x + v.y * v.y + v.z * v.z
                  val m = DoubleArray(9)
                  val rhs = DoubleArray(3)
                  for (i in 1..3) {
                      m[3 * (i - 1)] = 2.0 * (data[i].x - data[0].x)
                      m[3 * (i - 1) + 1] = 2.0 * (data[i].y - data[0].y)
                      m[3 * (i - 1) + 2] = 2.0 * (data[i].z - data[0].z)
                      rhs[i - 1] = n2(data[i]) - n2(data[0])
                  }
                  fun det(a: DoubleArray) =
                      a[0] * (a[4] * a[8] - a[5] * a[7]) - a[1] * (a[3] * a[8] - a[5] * a[6]) +
                          a[2] * (a[3] * a[7] - a[4] * a[6])
                  val d = det(m)
                  fun column(k: Int): Double {
                      val c = m.copyOf()
                      for (row in 0..2) c[3 * row + k] = rhs[row]
                      return det(c) / d
                  }
                  val c = Vec3(column(0), column(1), column(2))
                  return c to kotlin.math.sqrt(n2(Vec3(data[0].x - c.x, data[0].y - c.y, data[0].z - c.z)))
              }

              val (trueCentre, trueRadius) = closedForm()
              val centreError = kotlin.math.sqrt(
                  (centre.x - trueCentre.x) * (centre.x - trueCentre.x) +
                      (centre.y - trueCentre.y) * (centre.y - trueCentre.y) +
                      (centre.z - trueCentre.z) * (centre.z - trueCentre.z),
              )

              println(
                  """
                  ${data.size} fixed points, two free variables, no point unknowns at all
                  ceres       centre (${"%.9f".format(centre.x)}, ${"%.9f".format(centre.y)}, ${"%.9f".format(centre.z)})  radius ${"%.9f".format(radius)}
                  closed form centre (${"%.9f".format(trueCentre.x)}, ${"%.9f".format(trueCentre.y)}, ${"%.9f".format(trueCentre.z)})  radius ${"%.9f".format(trueRadius)}
                  centre off by ${"%.2e".format(centreError)}, radius off by ${"%.2e".format(kotlin.math.abs(radius - trueRadius))}
                  ${result.summary}
                  """.trimIndent(),
              )

              // The fitted sphere, as latitude and longitude circles.
              val steps = 72
              fun circle(build: (Double) -> Vec3): FLine {
                  val line = FLine()
                  for (i in 0..steps) {
                      val p = build(2.0 * Math.PI * i / steps)
                      if (i == 0) line.moveTo(p.x.toFloat(), p.y.toFloat(), p.z.toFloat())
                      else line.lineTo(p.x.toFloat(), p.y.toFloat(), p.z.toFloat())
                  }
                  line.stroked = true
                  line.filled = false
                  line.thickness = 1.0
                  line.color = vec(0.36, 0.78, 0.96, 0.55)
                  return line
              }

              val shell = buildList {
                  for (k in 1..7) {
                      val phi = Math.PI * k / 8.0
                      val z = radius * kotlin.math.cos(phi)
                      val ring = radius * kotlin.math.sin(phi)
                      add(circle { t -> Vec3(centre.x + ring * kotlin.math.cos(t), centre.y + ring * kotlin.math.sin(t), centre.z + z) })
                  }
                  for (k in 0..7) {
                      val theta = Math.PI * k / 8.0
                      add(
                          circle { t ->
                              val ring = radius * kotlin.math.sin(t)
                              Vec3(
                                  centre.x + ring * kotlin.math.cos(theta),
                                  centre.y + ring * kotlin.math.sin(theta),
                                  centre.z + radius * kotlin.math.cos(t),
                              )
                          },
                      )
                  }
              }

              val cross = 0.14f
              val centreMark = FLine()
                  .moveTo((centre.x - cross).toFloat(), centre.y.toFloat(), centre.z.toFloat())
                  .lineTo((centre.x + cross).toFloat(), centre.y.toFloat(), centre.z.toFloat())
                  .moveTo(centre.x.toFloat(), (centre.y - cross).toFloat(), centre.z.toFloat())
                  .lineTo(centre.x.toFloat(), (centre.y + cross).toFloat(), centre.z.toFloat())
                  .moveTo(centre.x.toFloat(), centre.y.toFloat(), (centre.z - cross).toFloat())
                  .lineTo(centre.x.toFloat(), centre.y.toFloat(), (centre.z + cross).toFloat())
              centreMark.stroked = true
              centreMark.filled = false
              centreMark.thickness = 3.0
              centreMark.color = vec(0.99, 0.96, 0.62, 1.00)

              val centreLines: List<FLine> = [centreMark]

              threeLines(
                  dots() + shell + centreLines,
                  channel = "fit3d",
                  name = "ceres-sphere",
                  height = 520,
                  autoFrame = true,
                  editable = false,
              )
              displayOpen("fit3d")

              markdown(
                  "fit",
                  """
                  ### A centre and a radius, solved for

                  Orange crosses are the fixed data. Blue is the sphere Ceres found; the yellow cross is
                  its centre — a free variable, not a point in the cloud. From a start six units away and
                  a radius an order of magnitude too small it lands on the closed-form circumcentre to
                  `${"%.2e".format(centreError)}`.

                  The whole residual is three lines of Kotlin:

                  ```kotlin
                  val centre = variable("centre", Vec3(6.0, -6.0, 6.0))
                  val radius = variable("radius", 0.1)
                  expression(emptyList(), [centre, radius]) { _, (c, r) ->
                      data.map { p -> (CeresExprVec.of(p) - c.vec()).length() - r.scalar }
                  }
                  ```

                  It names no point at all — every unknown here is a free variable.
                  """.trimIndent(),
              )
              displayOpen("fit")
          }
  - execute:
      box: ceres_free_variables_planes
  - wait:
      millis: 750
  - execute:
      box: ceres_free_variables_sphere
  - wait:
      millis: 750

before:
name: completion_rank_at_scale
description: |
  **Completion ranking at corpus scale.** Three boxes over the checked-in recording of 578 carets —
  no GPU, no window, no sidecar: everything here reads the corpus and calls the live server-side
  classifier in process.

    - **The corpus.** Reads `rank-corpus.tsv.gz`, reports the population, and plots the payload
      distribution.
    - **Category and prior.** Calls the *real*
      `KotlinSourceIndex.getCompletionCategoryForSymbol` with the real recorded `declaredIn`, rather
      than a fixture of what it used to answer.
    - **Re-run the decision.** Re-scores every caret through the shipped weights and shows what moved.

  The third box shells out to `tools/rank_weight_lab.py` and wants a spec file that
  `afield.runtime.completion.FieldSuggestPresentationTest` drops; if it says so, run that test once. The written-up
  version, with the full sweep and the falsification behind it, is
  `dev_docs/completion_rank_at_scale.md`, and the saved document at
  `dev_docs/agents/demos/completion_rank_at_scale/` is this same scene.
operations:
  - create:
      box: corpus
      name: "the corpus"
      frame: { x: 60.0, y: 40.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          // 1 / Where the corpus is, and what is in it.
          //
          // `src/jvmTest/resources/fieldSuggest/rank-corpus.tsv.gz` is 578 real completion carets, each one
          // recorded from the code-use semantic sidecar's own `/complete` -- the endpoint the editor posts to
          // per keystroke. This box reads the checked-in recording and shows you the population that a
          // weighting decision now rests on. Nothing here is a summary written by hand.
          //
          // Run me (cmd-Enter / the run gutter). See dev_docs/completion_rank_at_scale.md.

          import java.io.File
          import java.util.zip.GZIPInputStream

          // Field's working directory is the checkout it was started from; walk up to its root.
          // Spelled with explicit types on purpose: in the REPL a `generateSequence(...).firstOrNull { } ?: error(...)`
          // chain infers `Any` here, and the first `File(repo, ...)` below then fails to resolve a constructor.
          fun findRepoRoot(): File {
              var at: File? = File(".").absoluteFile
              while (at != null) {
                  val here: File = at
                  if (File(here, "settings.gradle.kts").exists()) return here
                  at = here.parentFile
              }
              // `throw` and not `error(...)`: inside a box, `error` resolves to a Box member that returns Unit,
              // so a function ending in it fails to compile with "missing return statement".
              throw IllegalStateException("no Field checkout above ${File(".").absolutePath} - start Field from the repo root")
          }
          val repo: File = findRepoRoot()
          val corpus = File(repo, "src/jvmTest/resources/fieldSuggest/rank-corpus.tsv.gz")

          val lines = GZIPInputStream(corpus.inputStream()).bufferedReader().readLines()
          val rows = lines.filter { it.startsWith("R\t") }.map { it.split('\t').drop(1) }
          val cases = lines.filter { it.startsWith("C\t") }.map { it.split('\t').drop(1) }

          // label, form, receiver, truth, base64(code), row indices
          val payloadSize = cases.map { it[5].split(',').size }
          val byForm = cases.groupBy { it[1] }

          // The last expression is what the box shows in its output panel.
          val report = buildString {
              appendLine("${corpus.name}  ${corpus.length() / 1024} KB on disk")
              appendLine("${cases.size} carets, ${payloadSize.sum()} payload rows, ${rows.size} distinct " +
                  "(${"%.1f".format(payloadSize.sum().toDouble() / rows.size)}x interning)")
              appendLine()
              for ((form, group) in byForm) {
                  val sizes = group.map { it[5].split(',').size }.sorted()
                  appendLine("  $form: ${group.size} carets, payload median ${sizes[sizes.size / 2]}, " +
                      "max ${sizes.last()}, ${group.count { it[5].split(',').size > 80 }} contested (> 80 rows, " +
                      "so the popup had to leave something out)")
              }
              appendLine()
              appendLine("  the receivers a person is actually completing on, most-recorded first:")
              cases.groupingBy { it[2].ifBlank { "(no receiver resolved)" } }.eachCount()
                  .entries.sortedByDescending { it.value }.take(12)
                  .forEach { appendLine("    ${it.value.toString().padStart(4)}  ${it.key}") }
          }

          // The distribution the 80-row cut acts on. Everything to the right of 80 is a caret where ranking
          // decides what a person can see and what they cannot.
          showSignals(
              "payload rows per caret, sorted" to payloadSize.sorted().map { it.toDouble() },
              channel = "plot",  // its own channel: `display` REPLACES one, and the report below owns "output"
              title = "what the 80-row cut acts on",
          )

          report
  - create:
      box: classify
      name: "category + prior"
      frame: { x: 60.0, y: 1040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          // 2 / The classification fix and the prior, live, on a receiver you choose.
          //
          // Last night's fix made a candidate's category come from WHERE IT IS DECLARED rather than from its bare
          // name, because `scale` is declared in 42 categorised files in this tree, `close` in 21, `copy` in 16.
          // This box calls the real thing -- `KotlinSourceIndex.getCompletionCategoryForSymbol`, with the real
          // `declaredIn` the sidecar recorded -- and puts the real `CommonMemberPrior.rankOf` next to it.
          //
          // What you should notice is that for `afield.geometry.path.FLine` the index says NOTHING (`declines`), and
          // that is the fix working: FLine.kt carries no `@file:CompletionCategory`, so rather than borrowing the
          // category of an unrelated namesake -- which is how `FLine.moveTo` came to be filed under **Math** and
          // rendered in a foreign section -- it declines, and the popup's category comes one step later in
          // `KotlinCompletionSupport.inferCompletionCategory`, from the *package* `afield.geometry.path` -> Graphics.
          // That last step is `internal`, so a box cannot call it; the corpus measurement in
          // FieldSuggestPresentationTest can, and its numbers are quoted at the bottom.
          //
          // Change RECEIVER and re-run: `java.lang.Math` is a type nobody here can annotate -- no prior, and the
          // index declines rather than borrowing -- which is exactly the population the deferred decision was
          // about. `afield.geometry.mesh.TriMesh` is another Field type.

          import afield.runtime.completion.CommonMemberPrior
          import afield.runtime.completion.KotlinSourceIndex
          import java.io.File
          import java.util.zip.GZIPInputStream

          val RECEIVER = "afield.geometry.path.FLine"

          // Field's working directory is the checkout it was started from; walk up to its root.
          // Spelled with explicit types on purpose: in the REPL a `generateSequence(...).firstOrNull { } ?: error(...)`
          // chain infers `Any` here, and the first `File(repo, ...)` below then fails to resolve a constructor.
          fun findRepoRoot(): File {
              var at: File? = File(".").absoluteFile
              while (at != null) {
                  val here: File = at
                  if (File(here, "settings.gradle.kts").exists()) return here
                  at = here.parentFile
              }
              // `throw` and not `error(...)`: inside a box, `error` resolves to a Box member that returns Unit,
              // so a function ending in it fails to compile with "missing return statement".
              throw IllegalStateException("no Field checkout above ${File(".").absolutePath} - start Field from the repo root")
          }
          val repo: File = findRepoRoot()

          val gz = File(repo, "src/jvmTest/resources/fieldSuggest/rank-corpus.tsv.gz")
          val lines = GZIPInputStream(gz.inputStream()).bufferedReader().readLines()
          val rows = lines.filter { it.startsWith("R\t") }.map { it.split('\t').drop(1) }
          val case = lines.filter { it.startsWith("C\t") }.map { it.split('\t').drop(1) }
              .first { it[2] == RECEIVER && it[1] == "bare" }

          // text, displayText, tail, icon, declaredIn, proximity
          val shown = case[5].split(',').map { rows[it.toInt()] }
          val classified = shown.map { r ->
              val fromIndex = KotlinSourceIndex
                  .getCompletionCategoryForSymbol(symbolName = r[0], declaredIn = r[4].ifBlank { null })
              Triple(r, fromIndex, CommonMemberPrior.rankOf(RECEIVER, r[0]))
          }

          // The rows with a prior first: a prior is the only thing that moves a member up the popup, and
