  re-rendered. Here each panel is a separate `ShaderNeuralParticles` with its weights set once, so
  the figure means the same thing every time it is built.

  It is also the clearest way to see the finding. The interpolation does not slide the C's mouth
  shut into an S — it **seals the C into a closed ring and re-opens it the other way**. The middle
  panel is that ring, and it is the tidiest form in the whole family: walked in source order its
  landing cloud measures about 0.6 of a letter's perimeter, *shorter* than either endpoint,
  because a circle is the shortest closed curve there is. The two outer panels are where the
  S's spine is pressing into a ring that has not finished being a ring, and those are the ones
  that read as letters from an alphabet nobody wrote.

  Three fields at once is also just a reasonable thing to want: the weight buffer is per-system,
  so one trained pair can drive any number of panels with no extra training and no extra shaders.
operations:
  - create:
      box: li_renderer
      name: renderer
      frame: { x: 40.0, y: 40.0, w: 300.0, h: 100.0 }
      properties:
        code: |
          import afield.graphics.vulkan.util.Options
          prop<Window>(window)
          prop<Renderer>(renderer)
          Options.enableHDR = false
          Options.profiling = false
          once.renderer {
              window = Window("Letter interpolation")
              Renderer(window)
          }
          println("renderer ready")
          start(renderer::run)
  - create:
      box: li_fields
      name: train both letters
      frame: { x: 380.0, y: 40.0, w: 320.0, h: 100.0 }
      properties:
        code: |
          import afield.ai.learning.FlowCoupling
          import afield.ai.learning.FlowMatchOptions
          import afield.ai.learning.contourComponents
          import afield.ai.learning.flowMatch

          prop<afield.simulation.particles.FlowMatchExport>(fieldA)
          prop<afield.simulation.particles.FlowMatchExport>(fieldB)

          val LETTERS = "C" to "S"
          val N = 512

          // Both fields must start from the *same* cloud. That is what gives a particle one start
          // point and two destinations, and it is also what makes the two normalisation frames
          // agree -- `blendWith` refuses to mix two coordinate systems, so sharing the cloud is a
          // requirement and not a tidiness.
          val source = (0 until N).map {
              val a = 2 * Math.PI * it / N
              vec(Math.cos(a), Math.sin(a), 0.0)
          }

          // A letter as N points in arc-length order, centred and scaled to unit RMS radius so
          // that both letters live in the same frame as the circle.
          fun glyph(ch: String): List<Vec3> {
              val parts = contourComponents(layoutText(ch, typeface("Helvetica", 300.0)).toFLines(), total = N, seed = 3)
              if (parts.size != 1) throw IllegalArgumentException("'$ch' has ${parts.size} closed contours; this scene pairs one circle with one contour, so pick a letter like C, S, E, F, L, T, V or Z")
              val p = parts[0]
              val cx = p.map { it.x.toDouble() }.average()
              val cy = p.map { it.y.toDouble() }.average()
              val rms = Math.sqrt(p.sumOf { (it.x - cx) * (it.x - cx) + (it.y - cy) * (it.y - cy) } / p.size)
              return p.map { vec((it.x - cx) / rms, (it.y - cy) / rms, 0.0) }
          }

          // Rotate and if necessary reverse the contour so index i starts near circle index i.
          // Without this each letter carries an arbitrary rotation relative to the circle, and --
          // worse for this scene -- a *different* one, so the two fields would disagree about
          // which part of the circle becomes which part of the glyph and the interpolation would
          // be comparing nothing.
          fun align(contour: List<Vec3>): List<Vec3> {
              var best = contour
              var bestCost = Double.MAX_VALUE
              for (reversed in listOf(false, true)) {
                  val base = if (reversed) contour.reversed() else contour
                  for (shift in 0 until N) {
                      var cost = 0.0
                      for (i in 0 until N) {
                          val q = base[(i + shift) % N]; val s = source[i]
                          cost += (q.x - s.x) * (q.x - s.x) + (q.y - s.y) * (q.y - s.y)
                          if (cost > bestCost) break
                      }
                      if (cost < bestCost) { bestCost = cost; best = List(N) { base[(it + shift) % N] } }
                  }
              }
              return best
          }

          // The same seed in both calls. Smile's Xavier initialisation is drawn from a generator
          // that `flowMatch` reseeds, so this really is the same starting point twice.
          fun train(target: List<Vec3>) = flowMatch(
              target, source,
              FlowMatchOptions(steps = 9000, coupling = FlowCoupling.PAIRED, seed = 7, hidden = intArrayOf(64, 64)),
          ).export()

          fieldA = train(align(glyph(LETTERS.first)))
          fieldB = train(align(glyph(LETTERS.second)))
          println("${LETTERS.first} and ${LETTERS.second}: ${fieldA.network.parameterCount} parameters each, one source of ${fieldA.sourceCount} points")
  - create:
      box: li_panels
      name: three pinned panels
      frame: { x: 740.0, y: 40.0, w: 320.0, h: 100.0 }
      properties:
        code: |
          import afield.simulation.particles.ShaderNeuralParticles
          import afield.simulation.particles.blendWith

          prop<List<afield.simulation.particles.ShaderNeuralParticles>>(panels)

          // 0.5 is the ring. The other two are where the form is buckling -- a ring with the S's
          // spine pressing into it -- and they are the reason this figure is not just "a circle".
          // 0.78 rather than 0.75 because the buckle is deepest a little past three quarters.
          val STOPS = listOf(0.25f, 0.5f, 0.78f)

          // `name` keeps each system's buffers and modules apart; without it the second one would
          // bind over the first. `viewCenter` is subtracted before the divide, so a negative x
          // moves that panel to the right of the screen.
          once.panels {
              STOPS.mapIndexed { i, _ ->
                  ShaderNeuralParticles(fieldA, renderer) {
                      name = "panel$i"
                      particleCount = 150_000
                      stepsPerCycle = 150
                      // Higher than the sweeping scene's: a still wants the arrived distribution
                      // crisp rather than the stream between shapes.
                      dwellCycles = 3f
                      viewScale = 4.6f
                      viewCenter = Vector2f((1 - i) * 5.2f, 0f)
                  }.also { it.installInto() }
              }
          }

          // Set once, not per frame. Each panel is a different field from the same trained pair.
          STOPS.forEachIndexed { i, t ->
              panels[i].updateWeights(fieldA.blendWith(fieldB, t).network)
              panels[i].settings.intensity = 1.1f
              panels[i].settings.arrivalBias = 0.6f
              panels[i].settings.pointSize = 1.5f
              panels[i].settings.sourceColor = vec(0.15, 0.45, 1.0, 1.0)
              panels[i].settings.targetColor = vec(1.0, 0.62, 0.22, 1.0)
          }
          println("panels at ${STOPS.joinToString(", ")}")
  - connect: { parent: li_renderer, child: li_fields }
  - connect: { parent: li_fields, child: li_panels }
  - launch: { box: li_renderer, property: code }
  - await: { wait: pending }
  - launch: { box: li_fields, property: code }
  - await: { wait: pending }
  - launch: { box: li_panels, property: code }
  - await: { wait: pending }

before:
name: logging_layer
description: |
  The log layer — channels, sinks, and the three different rules that select on a channel. Six boxes, one per thing on `public/docs/logging.md`, and every one of them reads the real objects a running Field is using rather than a description of them: `LogDispatcher`'s live sink list, `ConsoleMute`'s actual mute set, and `LogStream`'s actual subscription filter.
  The point of running these rather than reading them is box 3. `ConsoleMute.isMuted` compares the whole channel string, the pinned console splits on commas and compares a tag, and `LogStream`'s filter takes any case-insensitive substring — so one word selects three different sets of lines, and box 3 makes a real subscriber prove it.
  The saved document at `dev_docs/agents/demos/logging_layer/` is this same scene.
operations:
  - create:
      box: log_channels
      name: "A channel, and a sink of your own"
      frame: { x: 60.0, y: 40.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          import afield.ai.diagnostics.LogDispatcher
          import afield.ai.diagnostics.LogEvent
          import afield.ai.diagnostics.LogSink
          import afield.ai.diagnostics.withSink
          import afield.app.diagnostics.logging.lprintln

          // A channel is a comma-separated list of tags. Not a level, not a logger name, and
          // not a hierarchy — "error,mypage,disk" is three flat tags.
          //
          // A LogSink is a fun interface with one method, so a lambda is a sink. This one keeps
          // only my own lines: the dispatcher is global, and a live Field is logging its own
          // frame rate the whole time this box runs.
          val seen = mutableListOf<LogEvent>()
          val probe = LogSink { e -> if ("mypage" in e.channel) seen += e }

          // withSink attaches and detaches around the block, on any exit. That is not a
          // convenience: the sink list outlives your box, and LogDispatcher.log wraps every sink
          // in runCatching — so a sink leaked by an early return throws silently, forever.
          LogDispatcher.withSink(probe) {
              lprintln("info,mypage", "a plain line")
              lprintln("warning,mypage", "something to look at")
              lprintln("error,mypage,disk", "three tags, and no hierarchy among them")
          }

          display("main", Table(listOf("channel", "tags", "message"), title = "what one sink saw")
              .rows(seen.map { listOf(it.channel, it.channel.split(",").size, it.message) })
              .role("channel", CellRole.ACCENT))
  - create:
      box: log_mute
      name: "Muting compares the whole string"
      frame: { x: 60.0, y: 1040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          import afield.ai.diagnostics.ConsoleMute

          // The first of the three matchers, and the strictest: isMuted is
          //
          //     fun isMuted(channel: String): Boolean = channel in channels
          //
          // Exact membership of a set of whole channel strings. Nothing is split, so you cannot
          // mute a *tag* — only the exact spelling written at the call site.
          val spellings = listOf("info,boxes", "boxes,info", "info,boxes,extra", "info,Boxes", "boxes")

          display("main", Table(
              listOf("channel string", "isMuted"),
              title = "ConsoleMute compares the whole channel string",
              note = "the set this JVM booted with: " + ConsoleMute.channels.sorted().joinToString(", ")
          )
              .rows(spellings.map { listOf(it, ConsoleMute.isMuted(it)) })
              .role("channel string", CellRole.ACCENT)
              .roleBy("isMuted") { if (it == true) CellRole.WARN else CellRole.OK })

          // Change the set with -Dafield.log.mute=a;b or AFIELD_LOG_MUTE=a;b (semicolon
          // separated, exact strings), or a blank value to mute nothing.
  - create:
      box: log_filter
      name: "The log widget takes any substring"
      frame: { x: 60.0, y: 2040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          import afield.app.diagnostics.logging.lprintln
          import afield.app.server.LogStream

          // The third matcher, and the loosest. LogStream is the sink behind the log widget, and
          // its filter asks channel.contains(tag, ignoreCase = true) — a substring, not a tag.
          //
          // This is a real subscription against the real archive. sinceEpochMs keeps the
          // existing 20,000-record ring out of the replay, so what arrives is only what I emit.
          val pushed = mutableListOf<String>()
          LogStream.addSubscription(
              "logdemo-substring",
              LogStream.Filter(
                  channels = listOf("kotlin"),
                  sinceEpochMs = System.currentTimeMillis(),
                  limit = 50,
                  tail = true
              )
          ) { json -> pushed += json }

          val emitted = listOf("info,kotlin", "info,kotlinjs", "info,graphics")
          try {
              emitted.forEach { lprintln(it, "«logdemo» a line on $it") }
          } finally {
              LogStream.unsubscribe("logdemo-substring")
          }

          val matched = pushed.filter { "«logdemo»" in it }
              .map { it.substringAfter("\"channel\":\"").substringBefore("\"") }
              .toSet()

          // info,kotlinjs matches because "kotlin" is a prefix of "kotlinjs". The pinned console,
          // which splits on commas, would not pin it. Same word, two different answers — and 108
          // pairs of a real tag and a real channel in this tree differ the same way.
          display("main", Table(
              listOf("channel emitted", "pushed to the subscriber"),
              title = "a LogStream filter of [\"kotlin\"] against three channels",
              note = "${matched.size} of ${emitted.size} matched: kotlin is a tag in the first and only a " +
                  "substring in the second. The pinned console splits on commas, so it would take only the first."
          )
              .rows(emitted.map { listOf(it, it in matched) })
              .role("channel emitted", CellRole.ACCENT)
              .roleBy("pushed to the subscriber") { if (it == true) CellRole.OK else CellRole.DIM })
  - create:
      box: log_mute_is_console_only
      name: "Muting is a console policy, not a filter"
      frame: { x: 60.0, y: 3040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          import afield.ai.diagnostics.ConsoleMute
          import afield.ai.diagnostics.LogDispatcher
          import afield.ai.diagnostics.LogSink
          import afield.ai.diagnostics.withSink
          import afield.app.diagnostics.logging.lprintln

          // Muting does not drop the event. Both console sinks check the mute set and return
          // early; no other sink checks it at all. So a muted line is still in the log widget,
          // still in the archive, and still delivered to a sink of yours.
          val arrived = mutableSetOf<String>()
          val probe = LogSink { e -> if ("«logdemo»" in e.message) arrived += e.channel }

          val channels = listOf("info,boxes", "info,mypage") // the first is muted by default
          LogDispatcher.withSink(probe) {
              channels.forEach { lprintln(it, "«logdemo» a line on $it") }
          }

          display("main", Table(
              listOf("channel", "muted on the console", "reached my sink"),
              title = "muting keeps a line off the console, not out of the layer",
              note = "${arrived.size} of ${channels.size} arrived. Mute is for a channel too chatty " +
                  "for a terminal, not for one you want gone."
          )
              .rows(channels.map { listOf(it, ConsoleMute.isMuted(it), it in arrived) })
              .role("channel", CellRole.ACCENT)
              .roleBy("muted on the console") { if (it == true) CellRole.WARN else CellRole.DIM }
              .roleBy("reached my sink") { if (it == true) CellRole.OK else CellRole.BAD })
  - create:
      box: log_blocks
      name: "Blocks, and what the indent holds"
      frame: { x: 60.0, y: 4040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          import afield.ai.diagnostics.LogDispatcher
          import afield.ai.diagnostics.LogEvent
          import afield.ai.diagnostics.LogSink
          import afield.ai.diagnostics.withSink
          import afield.app.diagnostics.logging.lblock
          import afield.app.diagnostics.logging.lprintln

          // lblock brackets a scope with a BEGIN and an END event sharing a blockId, so a
          // consumer can fold what is between them.
          val all = mutableListOf<LogEvent>()
          val probe = LogSink { e -> all += e }

          LogDispatcher.withSink(probe) {
              lblock("info,logdemo", "«logdemo» outer") {
                  lprintln("info,logdemo", "«logdemo» inside outer")
                  lblock("info,logdemo", "«logdemo» inner") {
                      lprintln("info,logdemo", "«logdemo» inside inner")
                  }
              }
          }

          // An END event's message is only its own id, so it is picked up by blockId rather
          // than by text.
          val mineIds = all.filter { "«logdemo»" in it.message }.mapNotNull { it.blockId }.toSet()
          val mine = all.filter { "«logdemo»" in it.message || it.blockId in mineIds }
          val deepest = mine.filter { it.boundary == null }.maxByOrNull { it.indent.length }

          // The table's footnote prints the deepest line's raw indent. The nesting lives in a
          // thread-local `indent` string, and what it holds is not spaces: it is one block UUID
          // and a tab per level. PinnedConsole parses those tokens back out to find the open
          // block. StdoutLog does not — it concatenates the indent into the line, so on a plain
          // terminal a line inside an lblock is prefixed by a raw 36-character UUID.
          display("main", Table(
              listOf("depth", "boundary", "block", "message"),
              title = "two nested lblocks, as the dispatcher saw them",
              note = "the deepest line's raw indent: '" +
                  (deepest?.indent?.replace("\t", "\\t") ?: "") +
                  "' — block ids and tabs, not spaces"
          )
              .rows(mine.map { e ->
                  listOf(
                      e.indent.split("\t").count { it.isNotEmpty() },
                      e.boundary?.name ?: "—",
                      e.blockId?.take(8) ?: "—",
                      e.message.substringBefore(" - '")
                  )
              })
              .role("message", CellRole.ACCENT))
  - create:
      box: log_stats
      name: "Stat lines and the heatmap"
      frame: { x: 60.0, y: 5040.0, w: 340.0, h: 100.0 }
      properties:
        code: |
          import afield.app.diagnostics.logging.StatsHeatmap
          import afield.app.diagnostics.logging.formatMillis

          // A channel that reports a number every frame gets coloured by whether each value rose
          // or fell since that channel last reported the same key. The contract is only a string
          // format: key=value or key: value, optionally with a unit.
          //
          // formatMillis emits a unit that matches that grammar, which is why a slow compile
          // reads compile=1.63s rather than compile=1629ms.
          val durations = listOf(120_000L, 3_400_000L, 47_000_000L, 250_000_000L, 1_630_000_000L, 12_400_000_000L)
          val ladder = Table(
              listOf("nanoseconds", "formatted"),
              title = "formatMillis keeps digits where they matter",
              note = "more digits below a millisecond, plain integers past 100ms, decimal seconds past a second"
          )
              .rows(durations.map { listOf(it, formatMillis(it)) })
              .role("formatted", CellRole.ACCENT)

          val line = "fps=61.2 upload=3.4MB net:102% dropped=0"
          val torn = Table(
              listOf("fragment", "treated as"),
              title = "how a stats line is torn into colourable tokens",
              note = "history is kept per channel and per key, so two unrelated metrics sharing one " +
                  "channel do not colour each other"
          )
              .rows(StatsHeatmap.fragments("logdemo", line).map {
                  listOf("'${it.text}'", if (it.style == null) "plain text" else "number")
              })
              .roleBy("treated as") { if (it == "number") CellRole.ACCENT else CellRole.DIM }

          markdown("main", """
              ${ladder.h}

              ${torn.h}
          """.trimIndent())
  - execute: { box: log_channels, property: code }
  - await: {}
  - execute: { box: log_mute, property: code }
  - await: {}
  - execute: { box: log_filter, property: code }
  - await: {}
  - execute: { box: log_mute_is_console_only, property: code }
  - await: {}
  - execute: { box: log_blocks, property: code }
  - await: {}
  - execute: { box: log_stats, property: code }
  - await: {}

